"""Build a local approval board; never writes public site files."""
import json
from html import escape
from pathlib import Path
OUT=Path(__file__).resolve().parent
data=json.loads((OUT/'proposed-prices.json').read_text('utf8'))
variants=[('01','Чёрный павильон','hero-01-studio-v1.png','Товар в лучах софитов. Графитовая баня, янтарный свет и кислотно-жёлтая типографика. Самый спокойный и универсальный вариант.'),('02','Перекрасили пятницу','hero-02-painter-v1.png','Художник превращает деревянный Парус в чёрный. Оранжевый, лайм, мазки и живая сцена — сильный сюжет для рекламы.'),('03','Ночь больших скидок','hero-03-neon-v1.png','Квадро Хаус в чёрном боксе. Лайм, фиолетовый свет и большие цифры. Отдельно видны 55 000 ₽ Чёрной пятницы и ещё 20 000 ₽ на Делюкс.')]
cards=[]
for number,title,file,description in variants:
 assert (OUT/'images'/file).is_file()
 cards.append(f'<article id="v{number}"><div class="variant-heading"><span class="number">{number}</span><div><h2>{escape(title)}</h2><p>{escape(description)}</p></div><a class="open" href="images/{file}" target="_blank" rel="noopener">Открыть крупно ↗</a></div><a href="images/{file}" target="_blank" rel="noopener"><img src="images/{file}" alt="{escape(title)} — концепт первого экрана" loading="lazy"></a></article>')
money=lambda n:f'{n:,}'.replace(',',' ')+' ₽'
main_cards=[]
for key in ['comfort','deluxe']:
 r=next(r for r in data['rows'] if r['model']=='kvadro' and r['size']=='500' and r['package']==key)
 discounts='Чёрная пятница: −'+money(r['blackFridayDiscountRub'])
 if key=='deluxe':discounts+='<br>Дополнительно на Делюкс: −'+money(r['additionalDeluxeDiscountRub'])
 main_cards.append('<article class="main-price-card"><span class="bf-mark">ЧЁРНАЯ ПЯТНИЦА · 11–21.11</span><h3>Комплектация «'+r['packageName']+'»</h3><p>Цена вне акции <del>'+money(r['proposedReferencePriceRub'])+'</del></p><strong>от '+money(r['finalPriceRub'])+'</strong><p class="discounts">'+discounts+'</p><small>Скидки при заключении договора с 11.11 по 21.11.2026 включительно.</small></article>')
main_preview='<section class="prices" id="main-prices"><h2>Блок цен на основном сайте</h2><p>Пример: Квадро 5 м. Та же логика для всех моделей и размеров. В Делюксе итог сразу включает обе скидки.</p><div class="main-price-grid">'+''.join(main_cards)+'</div></section>'
rows=[]
for r in data['rows']:
 rows.append('<tr data-model="'+r['model']+'" data-package="'+r['package']+'">'+''.join('<td>'+escape(str(value))+'</td>' for value in [r['modelName'],r['sizeLabel'],r['packageName'],money(r['currentDisplayedPriceRub']),money(r['proposedReferencePriceRub']),'−'+money(r['blackFridayDiscountRub']),money(r['blackFridayPriceRub']),'−'+money(r['additionalDeluxeDiscountRub']) if r['additionalDeluxeDiscountRub'] else '—',money(r['finalPriceRub'])])+'</tr>')
html='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>ДачаПар · Чёрная пятница · 3 концепции</title>
<style>@font-face{font-family:Manrope;src:url('../../web/assets/manrope-cyrillic.woff2') format('woff2');font-display:swap}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#11120f;color:#f2f3e9;font-family:Manrope,Arial,sans-serif;line-height:1.6}main{max-width:1480px;margin:auto;padding:36px 24px 72px}header{max-width:980px;margin-bottom:36px}.eyebrow{color:#ddff38;letter-spacing:.08em;text-transform:uppercase;font-size:13px;font-weight:700}h1{font-size:clamp(34px,5vw,70px);line-height:1.03;letter-spacing:-.05em;margin:18px 0}h2{margin:0;font-size:clamp(22px,3vw,32px);line-height:1.2}p{margin:10px 0;color:#b8bcae}a{color:#e2ff47;text-underline-offset:5px}.tag{display:inline-block;border:1px solid #485138;border-radius:7px;padding:6px 12px;margin:5px 8px 5px 0;color:#e2ff47;font-size:14px}nav{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0}nav a,.open{padding:8px 12px;border:1px solid #4b5141;border-radius:8px;text-decoration:none;font-size:14px}article{border-top:1px solid #3b4032;padding:26px 0 44px}.variant-heading{display:flex;gap:20px;align-items:start;margin-bottom:20px}.variant-heading>div{flex:1}.variant-heading p{max-width:90ch}.number{color:#dfff36;font-size:30px;font-weight:700}.open{white-space:nowrap}article img{width:100%;height:auto;display:block;border:1px solid #393d31;border-radius:12px}.prices{border-top:1px solid #3b4032;padding-top:34px}.note{background:#25291e;padding:18px 22px;border:1px solid #53613b;border-radius:10px;color:#dbe4ce;margin:20px 0}.note strong{color:#ecff96}.filter{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}select{font:inherit;color:#f2f3e9;border:1px solid #536044;background:#1c2117;border-radius:7px;padding:8px 12px}.table-wrap{overflow:auto;border:1px solid #3d4534;border-radius:10px}table{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums;white-space:nowrap}th,td{text-align:left;padding:12px 14px;border-bottom:1px solid #303729}thead th{background:#252d1d;color:#e5f6d5;position:sticky;top:0}td:last-child{color:#dcff37;font-weight:800;font-size:16px}td:nth-child(5){color:#b3bca9}tbody tr:hover{background:#21281a}.files{display:flex;gap:20px;flex-wrap:wrap;margin-top:26px}footer{font-size:13px;color:#8d9580;margin-top:30px}@media(max-width:700px){main{padding:24px 14px}.variant-heading{gap:12px;flex-wrap:wrap}.open{margin-left:40px}.variant-heading>div{min-width:220px}article{padding-bottom:28px}.table-wrap{font-size:12px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}</style>
<main><header><span class="eyebrow">ДачаПар · дизайн на согласование</span><h1>Чёрная пятница.<br>Три разные сцены.</h1><p>11–21 ноября 2026 включительно · по московскому времени · скидка при заключении договора в период акции.</p><span class="tag">Ещё 20 000 ₽ на Делюкс — сохраняем</span><span class="tag">Макеты не опубликованы</span><nav><a href="#v01">01 · Павильон</a><a href="#v02">02 · Художник</a><a href="#v03">03 · Большие скидки</a><a href="#prices">Все 40 цен ↓</a></nav><p>Это направления первого экрана. При вёрстке цены и надписи будут обычными редактируемыми объектами, а выбранная модель будет переключать единую сцену и предложение.</p></header>
'''+''.join(cards)+'''
<section class="prices" id="prices"><h2>Цена: две скидки отдельно, один итог</h2><div class="note"><strong>Зачёркнутая сумма — предложенный новый прайс вне акции, подлежащий утверждению.</strong> Она не обозначается как подтверждённая историческая цена. Чёрная пятница даёт минус 5 000 ₽ к текущей показанной цене; для Делюкса дополнительно сохраняются ещё 20 000 ₽. При внедрении эта дополнительная скидка учитывается ровно один раз.</div><div class="filter"><label>Модель <select id="model"><option value="">Все модели</option><option value="kvadro">Квадро</option><option value="parus">Парус</option><option value="viking">Викинг</option><option value="kvadro-house">Квадро Хаус</option></select></label><label>Комплектация <select id="package"><option value="">Обе комплектации</option><option value="comfort">Комфорт</option><option value="deluxe">Делюкс</option></select></label></div><div class="table-wrap"><table><thead><tr><th>Модель</th><th>Размер</th><th>Комплектация</th><th>Сейчас на сайте</th><th>Прайс вне акции*</th><th>Скидка ЧП</th><th>Цена ЧП</th><th>Доп. Делюкс</th><th>Итог акции</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><p>Все 20 сочетаний модели и размера, 40 цен. Максимум Чёрной пятницы — 55 000 ₽. Общая выгода до 75 000 ₽ от нового прайса вне акции получается на Квадро Хаус Делюкс с учётом дополнительных 20 000 ₽.</p><p>Акция действует с 11.11.2026 00:00 до 21.11.2026 23:59:59 по Москве. Доставка и основание рассчитываются отдельно. Окончательные планировка и комплектация согласуются в договоре.</p><div class="files"><a href="CONCEPT.md">Концепция и путь клиента</a><a href="PRICES-REVIEW.md">Матрица цен</a><a href="proposed-prices.json">Данные расчёта JSON</a><a href="prompts.json">Промпты трёх макетов</a></div></section><footer>Изображения созданы встроенной генерацией на основе изображений бань ДачаПар. Геометрия и цвет согласуются по окончательному дизайну и выбранной модели. Основной сайт, цены и интеграции не изменены.</footer></main><script>for(const s of document.querySelectorAll('select'))s.addEventListener('change',()=>{const m=document.querySelector('#model').value,p=document.querySelector('#package').value;for(const row of document.querySelectorAll('tbody tr'))row.hidden=!!(m&&m!==row.dataset.model||p&&p!==row.dataset.package);});</script></html>'''
html=html.replace('<section class="prices" id="prices">',main_preview+'<section class="prices" id="prices">',1)
html=html.replace('</style>','.main-price-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:24px 0 40px}.main-price-card{margin:0;border:1px solid #aebb99;border-radius:16px;padding:26px;background:#f3f6e8;color:#233e2e}.main-price-card:last-child{background:#e4edcc}.main-price-card h3{font-size:23px;margin:18px 0 12px}.main-price-card p{color:#4d6045;font-size:14px}.main-price-card strong{font-size:clamp(30px,4vw,48px);line-height:1.2;letter-spacing:-.04em}.main-price-card small{display:block;margin-top:18px;font-size:12px;line-height:1.5}.main-price-card .discounts{font-weight:650;color:#294d30}.bf-mark{display:inline-block;background:#191d15;color:#dfff3a;padding:7px 10px;border-radius:6px;font-size:12px;font-weight:800}.main-price-card del{margin-left:6px;font-size:20px}@media(max-width:650px){.main-price-grid{grid-template-columns:1fr}}</style>',1)
(OUT/'index.html').write_text(html,encoding='utf8')
assert len(rows)==40
assert all(r['finalPriceRub']==r['proposedReferencePriceRub']-r['blackFridayDiscountRub']-r['additionalDeluxeDiscountRub'] for r in data['rows'])
print(json.dumps({'variants':len(variants),'price_rows':len(rows),'arithmetic':'PASS','published':False}))
